// Generated by `npm run gen:guides` from docs/api/*.md — do not edit.
export const GUIDE_FILES: Record<string, string> = {
  'getting-started':
    '# Getting started\n\nThe NotifyNow API is the same API the dashboard uses. Your server calls it with an **API key** instead of a login. Every request and response is JSON over HTTPS.\n\n- Base URL: `https://wa.notifynow.in/api/v1`\n- Header: `X-API-Key: cav_live_…`\n- Download: [OpenAPI](/api/v1/openapi.public.json) · [Postman collection](/api/v1/postman.json)\n\n## 1. Create a key\n\nIn the dashboard, go to **Settings → API keys → Create API key** (owners and admins):\n\n1. Choose only the scopes your system needs (see **Authentication**).\n2. Optionally limit the key to your servers\' IP addresses and set an expiry date.\n\nThe full key is shown **once**. Keep it in your server\'s secrets — never in a browser or a mobile app.\n\n## 2. Check the key\n\n```bash\ncurl https://wa.notifynow.in/api/v1/api-keys/whoami -H "X-API-Key: $NOTIFYNOW_KEY"\n```\n\n```json\n{\n  "success": true,\n  "data": {\n    "accountId": "…",\n    "apiKeyId": "…",\n    "scopes": ["resources:read", "contacts:write", "messages:write"]\n  }\n}\n```\n\n## 3. Find your ids\n\nCalls, campaigns and messages need ids of things set up in the dashboard. Read them with `resources:read`:\n\n| You need               | Call                                                      |\n| ---------------------- | --------------------------------------------------------- |\n| a flow `flowId`        | `GET /resources/flows`                                    |\n| an AI agent            | `GET /resources/agents`                                   |\n| a WhatsApp `channelId` | `GET /resources/whatsapp-numbers`                         |\n| a list / segment       | `GET /resources/contact-lists`, `GET /resources/segments` |\n| a caller number        | `GET /resources/phone-line`                               |\n| an IVR menu            | `GET /resources/ivrs`                                     |\n| the wallet balance     | `GET /resources/wallet`                                   |\n\n## 4. First calls\n\nUpsert a contact, send an approved template, then start a call:\n\n```bash\ncurl -X POST "https://wa.notifynow.in/api/v1/contacts?upsert=phone" \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -d \'{"phone":"+919000000001","name":"Asha Verma","externalId":"CRM-1001","variables":{"amount_due":2500000000}}\'\n\ncurl -X POST https://wa.notifynow.in/api/v1/messages/template \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: crm-1001-reminder-2026-11-05" \\\n  -d \'{"to":"+919000000001","template":{"name":"emi_reminder","language":"en"},"variables":{"1":"Asha","2":"₹2,500"},"externalRef":"CRM-1001"}\'\n\ncurl -X POST https://wa.notifynow.in/api/v1/calls \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: crm-1001-call-1" \\\n  -d \'{"contactId":"6720f0a1b2c3d4e5f6a7b8c9","flowId":"6720f0a1b2c3d4e5f6a7b8ca","externalRef":"CRM-1001"}\'\n```\n\n### Node.js\n\n```js\nconst api = (path, body, key) =>\n  fetch(`https://wa.notifynow.in/api/v1${path}`, {\n    method: body ? \'POST\' : \'GET\',\n    headers: {\n      \'X-API-Key\': process.env.NOTIFYNOW_KEY,\n      \'Content-Type\': \'application/json\',\n      ...(key ? { \'Idempotency-Key\': key } : {}),\n    },\n    body: body ? JSON.stringify(body) : undefined,\n  }).then(async (r) => {\n    const json = await r.json();\n    if (!json.success) throw new Error(`${json.error.code}: ${json.error.message}`);\n    return json.data;\n  });\n\nconst message = await api(\n  \'/messages/template\',\n  {\n    to: \'+919000000001\',\n    template: { name: \'emi_reminder\', language: \'en\' },\n    variables: { 1: \'Asha\', 2: \'₹2,500\' },\n  },\n  \'crm-1001-reminder-2026-11-05\',\n);\n```\n\n### Python\n\n```python\nimport os, requests\n\ndef api(path, body=None, key=None):\n    headers = {"X-API-Key": os.environ["NOTIFYNOW_KEY"]}\n    if key:\n        headers["Idempotency-Key"] = key\n    r = requests.request("POST" if body else "GET", f"https://wa.notifynow.in/api/v1{path}", json=body, headers=headers, timeout=30)\n    data = r.json()\n    if not data["success"]:\n        raise RuntimeError(f\'{data["error"]["code"]}: {data["error"]["message"]}\')\n    return data["data"]\n\nflows = api("/resources/flows")\n```\n\n### PHP\n\n```php\n<?php\nfunction notifynow(string $path, ?array $body = null, ?string $key = null): array {\n    $ch = curl_init("https://wa.notifynow.in/api/v1$path");\n    $headers = [\'X-API-Key: \' . getenv(\'NOTIFYNOW_KEY\'), \'Content-Type: application/json\'];\n    if ($key) $headers[] = "Idempotency-Key: $key";\n    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $headers]);\n    if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body));\n    $res = json_decode(curl_exec($ch), true);\n    if (!$res[\'success\']) throw new RuntimeException($res[\'error\'][\'code\']);\n    return $res[\'data\'];\n}\n```\n\n`externalRef` (up to 100 characters) is your own id. It comes back on the call or message and in webhooks.\n\n## 5. Get results\n\nAdd a webhook endpoint (**Webhooks**) instead of polling. Every event is signed; deliveries retry for 12 hours.\n\n## Rules worth knowing\n\n- **Account boundary:** a key sees only its own account. Another account\'s id answers `404`.\n- **Customer protections:** keys never see full phone numbers in exports, and the API can never clear an opt-out or a do-not-call entry.\n- **Revocation:** a revoked or expired key stops working within 30 seconds.\n',
  authentication:
    '# Authentication\n\nSend your key in the `X-API-Key` header on every request. Keys start with `cav_live_`.\n\n- **Scopes:** each route needs exactly one scope (shown as `x-scope` on every operation). A key without it gets `403 AUTH_FORBIDDEN` with `details: [{ "path": "scope", "message": "<scope> is required" }]`.\n- **IP allowlist:** optional IPv4 / IPv6 addresses or ranges; other callers get `403 API_KEY_IP_DENIED`.\n- **Expiry:** optional; after it the key gets `401 API_KEY_EXPIRED`.\n- **Rotation:** create a new key, deploy it, then revoke the old one (revocation applies within 30 s).\n- **Request log:** Settings → API keys shows each key\'s last 7 days of requests (route, status, time — never bodies).\n\n| Answer | Meaning                                                                     |\n| ------ | --------------------------------------------------------------------------- |\n| `401`  | No key, a wrong key, an expired or revoked key                              |\n| `403`  | The key lacks the scope, the IP is not allowed, or the account is suspended |\n| `404`  | The id is not in this account (also for other accounts\' ids)                |\n\n## Scopes\n\n<!-- scopes:start -->\n\n| Scope                      | Group     | Lets the key                                                                                          |\n| -------------------------- | --------- | ----------------------------------------------------------------------------------------------------- |\n| `calls:read`               | Calls     | Read call records and results                                                                         |\n| `calls:write`              | Calls     | Trigger calls                                                                                         |\n| `whatsapp-calls:write`     | Calls     | Start WhatsApp calls with an AI agent                                                                 |\n| `contacts:read`            | Contacts  | Read contacts                                                                                         |\n| `contacts:write`           | Contacts  | Create and update contacts                                                                            |\n| `campaigns:read`           | Campaigns | Read campaigns and their status                                                                       |\n| `campaigns:write`          | Campaigns | Create and control campaigns                                                                          |\n| `messages:read`            | WhatsApp  | Read WhatsApp messages sent by the API                                                                |\n| `messages:write`           | WhatsApp  | Send WhatsApp messages and templates                                                                  |\n| `templates:read`           | WhatsApp  | Read approved WhatsApp templates                                                                      |\n| `reports:read`             | Reports   | Read report numbers                                                                                   |\n| `exports:write`            | Reports   | Create and download exports                                                                           |\n| `webhooks:manage`          | Webhooks  | Manage outbound webhooks                                                                              |\n| `whatsapp-campaigns:read`  | WhatsApp  | Read WhatsApp bulk campaigns, recipients and reports                                                  |\n| `whatsapp-campaigns:write` | WhatsApp  | Create, start and control WhatsApp bulk campaigns                                                     |\n| `resources:read`           | Account   | Read flows, AI agents, WhatsApp numbers, lists, segments, caller numbers, IVRs and the wallet balance |\n\n<!-- scopes:end -->\n',
  conventions:
    '# Conventions\n\n| Thing          | Format                                                                                                                       |\n| -------------- | ---------------------------------------------------------------------------------------------------------------------------- |\n| Phones         | E.164, e.g. `+919000000001`. Indian 10-digit numbers you send get `+91`. Lists show only the last 4 digits (`phoneLast4`).   |\n| Money          | Integer **micros**: ₹1 = `1000000`; `2500000000` = ₹2,500.                                                                   |\n| Times          | ISO 8601 in UTC (`2026-11-05T09:30:00.000Z`). Calling windows and reports use the account timezone (default `Asia/Kolkata`). |\n| Ids            | 24-character hex strings. Treat them as opaque.                                                                              |\n| `externalRef`  | Your own id (≤ 100 chars) on calls and messages; echoed in webhooks.                                                         |\n| Envelope       | Success: `{ "success": true, "data": …, "meta"?: … }`. Error: see **Errors**.                                                |\n| Unknown fields | Refused with `422` (no silent typos).                                                                                        |\n\nPersonal data: contact names and phones appear only where the route is about that contact. Webhooks carry personal data only to endpoints with **Include personal data** on.\n',
  errors:
    '# Errors\n\nEvery error has the same shape, with an HTTP status and a stable `code`:\n\n```json\n{\n  "success": false,\n  "error": {\n    "code": "VALIDATION_FAILED",\n    "message": "Check the highlighted fields.",\n    "details": [{ "path": "body.phone", "message": "Not a valid phone number" }],\n    "requestId": "8a1c2f0e-…"\n  }\n}\n```\n\nQuote `requestId` when you contact support. Branch on `code`, never on `message` — messages can change.\n\n**Retry** only `429` (after `Retry-After`), `5xx` and network errors — with the **same** `Idempotency-Key`. Other `4xx` answers will not change until you change the request.\n\n## Codes on public routes\n\n<!-- errors:start -->\n\n| Code                               | Status | What to do                                                                |\n| ---------------------------------- | ------ | ------------------------------------------------------------------------- |\n| `REQUEST_MALFORMED`                | 400    | Send valid JSON.                                                          |\n| `VALIDATION_FAILED`                | 422    | Fix the fields listed in `details` (path + message).                      |\n| `PAYLOAD_TOO_LARGE`                | 413    | Send a smaller body (1 MB) or fewer rows.                                 |\n| `RATE_LIMITED`                     | 429    | Wait `Retry-After` seconds, then retry.                                   |\n| `IDEMPOTENCY_KEY_REUSED`           | 422    | Use a new `Idempotency-Key` for a different request.                      |\n| `IDEMPOTENCY_IN_PROGRESS`          | 409    | The first request with this key is still running — retry shortly.         |\n| `RESOURCE_NOT_FOUND`               | 404    | The id does not exist in this account.                                    |\n| `CONFLICT_DUPLICATE`               | 409    | A record with this phone / external id / name exists — see `details`.     |\n| `CONFLICT_INVALID_STATE`           | 409    | The status does not allow this now — read the message.                    |\n| `AUTH_UNAUTHENTICATED`             | 401    | Send a valid `X-API-Key`.                                                 |\n| `AUTH_FORBIDDEN`                   | 403    | Add the scope in `details[0]` to the key, or call from an allowed IP.     |\n| `API_KEY_EXPIRED`                  | 401    | Create a new key.                                                         |\n| `API_KEY_IP_DENIED`                | 403    | Call from an IP on the key’s allowlist.                                   |\n| `WALLET_INSUFFICIENT_BALANCE`      | 422    | Add money to the wallet.                                                  |\n| `WALLET_BUDGET_EXCEEDED`           | 422    | Raise the monthly budget in Wallet → Settings.                            |\n| `CONTACT_OPTED_OUT`                | 422    | The contact opted out — do not message them.                              |\n| `WHATSAPP_WINDOW_CLOSED`           | 409    | Outside 24 hours since the customer wrote: send a template.               |\n| `TEMPLATE_NOT_FOUND`               | 404    | Check the template name and language (`GET /whatsapp/templates`).         |\n| `TEMPLATE_NOT_APPROVED`            | 409    | Only `APPROVED` templates can be sent.                                    |\n| `TEMPLATE_PAUSED`                  | 409    | WhatsApp paused this template — use another one.                          |\n| `TEMPLATE_VARIABLES_MISSING`       | 422    | Give every template variable a value.                                     |\n| `CALL_LIMIT_REACHED`               | 429    | Too many calls at once for the account — retry later.                     |\n| `CALL_CAPACITY`                    | 503    | The server is busy — retry later.                                         |\n| `LINE_BUSY`                        | 409    | Every phone line is in use — retry later (campaigns wait by themselves).  |\n| `NUMBER_NOT_ALLOWED`               | 422    | Only Indian mobiles and landlines can be called on the phone line.        |\n| `CALLER_NUMBER_INVALID`            | 422    | Use a caller number from `GET /resources/phone-line`.                     |\n| `CAMPAIGN_NOT_RUNNABLE`            | 409    | Fix what `details` lists (flow, agent, audio, audience), then start.      |\n| `CAMPAIGN_LIMIT_REACHED`           | 429    | Too many active campaigns — finish or cancel one.                         |\n| `CAMPAIGN_REVISION_CONFLICT`       | 409    | Someone else changed the campaign — read it again.                        |\n| `WA_CAMPAIGN_NOT_EDITABLE`         | 409    | A started bulk campaign cannot be edited.                                 |\n| `WA_CAMPAIGN_AUDIENCE_EMPTY`       | 422    | Nobody in the audience can get the message (opted out, DND, no WhatsApp). |\n| `WHATSAPP_CALL_PERMISSION_MISSING` | 409    | The customer has not allowed calls from this number — ask first.          |\n| `WHATSAPP_CALLING_DISABLED`        | 409    | Turn calling on for this WhatsApp number.                                 |\n| `WHATSAPP_CALL_LIMIT_REACHED`      | 429    | WhatsApp’s call limit for this customer is reached — try later.           |\n| `WEBHOOK_URL_BLOCKED`              | 422    | Use a public https URL.                                                   |\n| `REPORT_RANGE_INVALID`             | 422    | Use a range of at most 366 days, `from` before `to`.                      |\n| `VOICE_API_NOT_ENABLED`            | 403    | Recorded voice is not on for the account — contact support.               |\n| `VOICE_API_NOT_PRICED`             | 409    | Recorded voice has no price yet — contact support.                        |\n| `VOICE_API_AUDIO_INVALID`          | 422    | Use your own WAV / MP3 of at most 120 seconds.                            |\n| `VOICE_API_IVR_MISSING`            | 409    | Use an IVR from `GET /resources/ivrs`.                                    |\n| `PROVIDER_ERROR`                   | 502    | The provider refused the request — read the message.                      |\n| `PROVIDER_UNAVAILABLE`             | 503    | A provider is down — retry later with the same `Idempotency-Key`.         |\n| `INTERNAL_ERROR`                   | 500    | Retry later; quote `requestId` to support if it repeats.                  |\n\n<!-- errors:end -->\n',
  idempotency:
    '# Idempotency\n\n`POST` requests that cost money or reach your customers need an **`Idempotency-Key`** header. Examples are sending a message, starting a call and starting a campaign. Use any unique string of your own, such as your record id plus the action.\n\n- The same key and the same body within **24 hours** returns the first response again, with `Idempotent-Replayed: true`. Nothing is sent twice.\n- The same key with a **different** body gets `422 IDEMPOTENCY_KEY_REUSED`.\n- The same key while the first request is still running gets `409 IDEMPOTENCY_IN_PROGRESS`. Retry in a moment.\n- `5xx` answers are not stored, so a retry with the same key runs again.\n\nRetry network errors and `5xx` answers with the **same** key. Use a **new** key only for a new action.\n',
  'rate-limits':
    "# Rate limits\n\nEach key may make **600 reads** (`GET`) and **60 writes** (`POST` / `PATCH` / `DELETE`) a minute. Every response carries `RateLimit-Limit`, `RateLimit-Remaining` and `RateLimit-Reset`. Over the limit the API answers `429 RATE_LIMITED` with `Retry-After` (seconds).\n\nBack off and retry:\n\n```js\nasync function withRetry(call, tries = 5) {\n  for (let i = 0; ; i += 1) {\n    const res = await call();\n    if (res.status !== 429 || i === tries - 1) return res;\n    const wait = Number(res.headers.get('retry-after') ?? 1) * 1000;\n    await new Promise((r) => setTimeout(r, wait + Math.random() * 250));\n  }\n}\n```\n\n- Use bulk routes: `POST /contacts/bulk-upsert` (1,000 rows), campaigns instead of one call per contact.\n- Use webhooks instead of polling.\n- Ask support if your account needs higher limits.\n\n## Route-specific limits\n\n| Route                        | Limit                   |\n| ---------------------------- | ----------------------- |\n| `POST /whatsapp-campaigns`   | 30 per hour per account |\n| `POST /whatsapp/calls`       | 10 per minute           |\n| `POST /webhooks/voice-api/…` | provider only           |\n\n## Sending speed\n\nWhatsApp bulk campaigns are paced per WhatsApp number: **75 messages / second** on a confirmed Cloud API number, **18 / second** on a Business App (coexistence) or unconfirmed number, and by the number's daily messaging tier. Recorded-voice campaigns dial about 4 calls at a time on the provider's line.\n",
  pagination:
    '# Pagination\n\nLists are paged. Large, growing lists such as calls and messages use a **cursor**:\n\n```\nGET /api/v1/calls?limit=50\n→ "meta": { "nextCursor": "eyJj…", "hasMore": true }\nGET /api/v1/calls?limit=50&cursor=eyJj…\n```\n\nPass `nextCursor` back as `cursor` until `hasMore` is `false`. Cursors are opaque, so don\'t build or change them. Smaller lists (contacts, WhatsApp bulk campaigns and recipients) use pages (`?page=2&limit=50` → `meta.page`, `meta.total`, `meta.totalPages`). Account resources (`/resources/*`) answer at most 200 rows, newest first, without paging.\n\n`limit` is at most 100. Unknown query parameters are refused (`422`), so typos never pass silently.\n\nDates are ISO 8601 in UTC (`2026-10-30T05:00:00.000Z`). Money is in integer micro-units (`2500000000` = ₹2,500). Phones are E.164 (`+919876543210`).\n',
  'whatsapp-messages':
    '# WhatsApp messages\n\n1. Find the sending number: `GET /resources/whatsapp-numbers` (`id` = `channelId`).\n2. Find an approved template: `GET /whatsapp/templates?status=APPROVED&channelId=…` (templates belong to the WhatsApp Business Account; numbers of the same account share them).\n3. Send it: `POST /messages/template` with `Idempotency-Key`.\n\n```bash\ncurl -X POST https://wa.notifynow.in/api/v1/messages/template \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: order-881-shipped" \\\n  -d \'{"channelId":"6720f0a1b2c3d4e5f6a7b8d1","to":"+919000000001","template":{"name":"order_shipped","language":"en"},"variables":{"1":"Asha","2":"881"}}\'\n```\n\n- **Variables:** numbered (`"1"`, `"2"`) or named, exactly as in the template. Missing ones answer `422 TEMPLATE_VARIABLES_MISSING`.\n- **Header media:** `header: { "mediaToken": "…" }` (an uploaded file) or `header: { "location": { … } }` when the template has such a header.\n- **Text:** `POST /messages/text` works only within 24 hours of the customer\'s last message (`409 WHATSAPP_WINDOW_CLOSED` otherwise).\n- **Status:** `GET /messages/{id}` or the `whatsapp.message.status` webhook: `queued → sent → delivered → read`, or `failed` with WhatsApp\'s error code.\n- **Price:** by template category (marketing / utility / authentication / service) and the destination country, held at send and charged when WhatsApp bills it; see the wallet ledger.\n- **Opt-out:** contacts who wrote STOP (or are on do-not-call) are refused with `CONTACT_OPTED_OUT`. Only a person in the dashboard can opt them back in.\n\nFor many recipients use **WhatsApp bulk campaigns** instead of a loop.\n',
  calls:
    '# Calls\n\n`POST /calls` calls one contact now with a published **flow** (`flowId`, optional `version`) or an active **AI agent** (`agentId`) — ids from `GET /resources/flows` and `GET /resources/agents`.\n\n```bash\ncurl -X POST https://wa.notifynow.in/api/v1/calls \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: loan-1001-call-1" \\\n  -d \'{"contactId":"6720f0a1b2c3d4e5f6a7b8c9","agentId":"6720f0a1b2c3d4e5f6a7b8cb","variables":{"amount_due":"₹2,500"},"externalRef":"loan-1001"}\'\n```\n\n- **Line:** `GET /resources/phone-line` — `sip` dials real phones; `dryrun` (test line) simulates the customer and never charges.\n- **Caller number:** `callerNumberId` from the phone line (default: the account\'s first number).\n- **Variables:** seed flow variables or the agent\'s allowed values.\n- **Guards:** calling window (09:00–21:00 at most), DND / opt-out, daily / weekly caps per contact, wallet, concurrency.\n- **Results:** `GET /calls/{id}` (status, end reason, duration, disposition, outcome, cost), `/transcript`, `/insights` (AI summary, sentiment, promise to pay), `/after-call` (WhatsApp sent after the call), or the `call.completed` / `call.insights.ready` webhooks.\n- **Cost:** carrier minutes by pulse + AI minutes, in micros (`cost.totalMicros`).\n\n## Incoming calls\n\nCustomers can call your numbers too (Phase 20). Who answers is set in the app (**Settings → Phone numbers**): a flow or AI agent, your team in the browser, AI that can hand over to the team, or the team with AI when nobody picks up — plus call hours and what happens after hours.\n\n- **Your numbers:** `GET /resources/phone-line` → `inboundNumbers` (number, label, on / off, route).\n- **Incoming calls:** `GET /calls?direction=inbound` — `inbound.did` is the number the customer dialed; `from` is the caller (`anonymous` when hidden).\n- **Missed calls (callback list):** `GET /calls?missed=open` — calls nobody (person or AI) took, with `missed.reason`: `no_answer`, `no_agents`, `after_hours`, `line_busy`, `wallet_low`, `caller_hung_up`. Calling the customer back (`POST /calls`) clears their missed calls of the last 24 hours.\n- **Webhooks:** `call.started` / `call.completed` carry `direction` and `did`; `call.missed` arrives for each missed call.\n- **Cost:** incoming minutes at the incoming minute price (`GET /wallet/rates` → `inboundCallPerMinuteMicros`) + AI minutes; missed calls and after-hours / low-wallet messages are free.\n',
  'whatsapp-calls':
    '# WhatsApp calls\n\n1. A calling-ready number: `GET /resources/whatsapp-numbers` → `calling.ready: true` (Business App numbers cannot call).\n2. The customer must have **allowed calls from that number** (they accept a call-permission request; permissions expire). Otherwise `409 WHATSAPP_CALL_PERMISSION_MISSING`.\n3. Optional price: `GET /whatsapp/channels/{id}/calling/quote?contactId=…` (selling price per minute).\n4. Call: `POST /whatsapp/calls` with `mode: "ai"` and `program` (a published flow or an active agent).\n\n```bash\ncurl -X POST https://wa.notifynow.in/api/v1/whatsapp/calls \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: wa-call-1001" \\\n  -d \'{"channelId":"6720f0a1b2c3d4e5f6a7b8d1","contactId":"6720f0a1b2c3d4e5f6a7b8c9","mode":"ai","program":{"kind":"agent","id":"6720f0a1b2c3d4e5f6a7b8cb"}}\'\n```\n\nResults come as `GET /calls/{id}` (provider `whatsapp`) and the `whatsapp.call.started` / `whatsapp.call.ended` webhooks. Business-initiated calls are charged per 6-second pulse; customer-initiated calls are free. For many customers use a campaign with `line: "whatsapp"`.\n',
  campaigns:
    '# Campaigns\n\nFour kinds, two APIs:\n\n| Kind                   | API                                        | What runs                                                                                        |\n| ---------------------- | ------------------------------------------ | ------------------------------------------------------------------------------------------------ |\n| SIP / normal calls     | `POST /campaigns` with `line: "phone"`     | a published flow or AI agent on the phone line (`mode: live`) or the test line (`mode: dry_run`) |\n| WhatsApp calls         | `POST /campaigns` with `line: "whatsapp"`  | a flow or agent over WhatsApp calls, only to people who allowed calls                            |\n| Recorded voice / IVR   | `POST /campaigns` with `line: "voice_api"` | one audio file or IVR menu played by the provider                                                |\n| WhatsApp bulk messages | `POST /whatsapp-campaigns`                 | approved templates only                                                                          |\n\n## Call campaigns\n\nLifecycle: **create** (draft) → **estimate** (`POST /campaigns/{id}/estimate`) → **start** (`Idempotency-Key`) → `pause` / `resume` / `cancel` → results in `GET /campaigns/{id}/contacts`, exports, and the `campaign.completed` webhook.\n\n```bash\ncurl -X POST https://wa.notifynow.in/api/v1/campaigns \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -d \'{"name":"November EMI calls","mode":"live","line":"phone","flowId":"6720f0a1b2c3d4e5f6a7b8c9","audience":{"listIds":["6720f0a1b2c3d4e5f6a7b8ca"]},"window":{"start":"10:00","end":"19:00","days":[1,2,3,4,5,6]}}\'\n\ncurl -X POST https://wa.notifynow.in/api/v1/campaigns/6720f0a1b2c3d4e5f6a7b8cc/start \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Idempotency-Key: nov-emi-start"\n```\n\n- **Audience:** `listIds`, `segmentId`, a contact `filter` or `contactIds`. At start the audience is snapshotted: DND, opted-out, invalid and duplicate numbers (and contacts in other active campaigns, unless turned off) are skipped with a reason.\n- **Window & retries:** calls only inside the window (09:00–21:00 at most); `retry` redials no-answer / busy / failed.\n- **Schedule:** `schedule.startAt` for later, `schedule.recurrence` for daily / weekly runs (`GET /campaigns/{id}/runs`).\n\n### Recorded voice (`line: "voice_api"`)\n\n```json\n{\n  "name": "Payment reminder (voice)",\n  "line": "voice_api",\n  "voiceApi": {\n    "content": { "kind": "audio", "flowAudioId": "6720f0a1b2c3d4e5f6a7b8cd" },\n    "retries": 1,\n    "retryIntervalMin": 30\n  },\n  "audience": { "listIds": ["6720f0a1b2c3d4e5f6a7b8ca"] }\n}\n```\n\n- Content: your own audio (WAV / MP3 ≤ 120 s, uploaded in the dashboard) or `{ "kind": "ivr", "ivrId": … }` from `GET /resources/ivrs`.\n- Only 10-digit Indian mobiles are called (others skipped `not_indian_mobile`). Always live; no dry run.\n- Numbers go to the provider in **batches**; each number is charged per started 15 seconds **when its batch is sent**, answered or not. Redials (0–3) are done by the provider and must fit in the window.\n- **Stop / cancel** holds back numbers not yet sent; numbers already sent keep ringing.\n- Results: `voice` on each row of `GET /campaigns/{id}/contacts` (provider status, duration, key pressed) and one call per number (`provider: voice_api`).\n\n## WhatsApp bulk campaigns\n\nScopes `whatsapp-campaigns:read` / `whatsapp-campaigns:write`.\n\n```bash\ncurl -X POST https://wa.notifynow.in/api/v1/whatsapp-campaigns \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Content-Type: application/json" \\\n  -d \'{"name":"November EMI reminder","channelId":"6720f0a1b2c3d4e5f6a7b8d1","variants":[{"key":"A","templateId":"6720f0a1b2c3d4e5f6a7b8d2","splitPct":100}],"variables":{"1":{"kind":"contact.name"}},"audience":{"listIds":["6720f0a1b2c3d4e5f6a7b8ca"]}}\'\n\ncurl -X POST https://wa.notifynow.in/api/v1/whatsapp-campaigns/6720f0a1b2c3d4e5f6a7b8c9/estimate -H "X-API-Key: $NOTIFYNOW_KEY"\ncurl -X POST https://wa.notifynow.in/api/v1/whatsapp-campaigns/6720f0a1b2c3d4e5f6a7b8c9/start \\\n  -H "X-API-Key: $NOTIFYNOW_KEY" -H "Idempotency-Key: nov-reminder-start"\n```\n\n- Approved templates only; up to 3 variants for an A/B split (optionally pick a winner by read / reply after N hours).\n- Variables: `contact.name`, `contact.phone`, a contact `field` or `static` text.\n- Speed: 75 / second (Cloud API number) or 18 / second (Business App / unconfirmed), within the number\'s daily tier.\n- Each message is charged when WhatsApp bills it. Results: `GET /whatsapp-campaigns/{id}` counters, `/recipients`, `/report`, `/export`, and the `whatsapp_campaign.completed` / `whatsapp_campaign.paused` webhooks.\n',
  'reports-exports':
    '# Reports and exports\n\n**Reports** (`reports:read`): `GET /reports/{tab}` for `overview`, `calls`, `whatsapp`, `templates`, `campaigns`, `flows`, `agents`, `team`.\n\n```bash\ncurl "https://wa.notifynow.in/api/v1/reports/campaigns?from=2026-11-01&to=2026-11-05&compare=true" -H "X-API-Key: $NOTIFYNOW_KEY"\n```\n\n- `from` / `to` are days in the account timezone, at most 366 days apart; `compare=true` adds the previous period.\n- Answers are cached for 60 seconds and carry an `ETag`; send `If-None-Match` to get `304`.\n\n**Exports** (`exports:write`): `POST /exports/calls`, `/exports/messages`, `/exports/report` answer an export job.\n\n1. Start the export (CSV or XLSX, at most 200,000 rows; one at a time per account).\n2. Poll `GET /exports/{id}` every few seconds until `status: "ready"`.\n3. Download from its URL within 15 minutes (read the job again for a fresh link).\n\nPhones are masked for API keys; message exports never contain message text.\n',
  webhooks:
    '# Webhooks\n\nNotifyNow sends events to your server as HTTPS `POST` requests. Add endpoints in **Integrations → Webhooks** (owners / admins) or with the API (`/api/v1/webhook-endpoints`, scope `webhooks:manage`).\n\n## The request\n\n```http\nPOST /your/path HTTP/1.1\nContent-Type: application/json\nUser-Agent: NotifyNow-Webhooks/1.0\nX-Webhook-Id: evt_01JBCDEFGHJKMNPQRSTVWXYZ01\nX-Webhook-Timestamp: 1761700000\nX-Webhook-Signature: v1=d8605653d430091a…\n\n{"id":"evt_01JBCDEFGHJKMNPQRSTVWXYZ01","type":"call.completed","apiVersion":"2026-10","createdAt":"2026-10-29T01:06:40.000Z","accountId":"…","data":{…}}\n```\n\nAnswer with any `2xx` within **10 seconds**. Anything else (including redirects — they are never followed) is a failure.\n\n## Verifying the signature\n\n`X-Webhook-Signature` is `v1=` + the hex HMAC-SHA256 of `"<X-Webhook-Timestamp>.<raw body>"`, keyed with your endpoint\'s secret exactly as shown (`whsec_…`). During a secret rotation the header carries two values (`v1=<new>, v1=<old>`) for 24 hours — accept the request if any value matches.\n\n1. Read the **raw** body bytes (before any JSON parsing).\n2. Reject the request if `X-Webhook-Timestamp` is more than 5 minutes from your clock.\n3. Compute the HMAC and compare with each `v1=` value in constant time.\n4. De-duplicate on `id` (deliveries are at-least-once).\n\n### Node.js\n\n```js\nconst crypto = require(\'node:crypto\');\n\n/** `rawBody` = the exact bytes received (e.g. express.raw({ type: \'application/json\' })). */\nfunction verifyNotifyNow(rawBody, headers, secret, toleranceSec = 300) {\n  const ts = Number(headers[\'x-webhook-timestamp\']);\n  if (!Number.isInteger(ts) || Math.abs(Date.now() / 1000 - ts) > toleranceSec) return false;\n  const expected = crypto.createHmac(\'sha256\', secret).update(`${ts}.`).update(rawBody).digest();\n  return String(headers[\'x-webhook-signature\'] || \'\')\n    .split(\',\')\n    .map((part) => part.trim())\n    .filter((part) => part.startsWith(\'v1=\'))\n    .some((part) => {\n      const given = Buffer.from(part.slice(3), \'hex\');\n      return given.length === expected.length && crypto.timingSafeEqual(given, expected);\n    });\n}\n```\n\n### Python\n\n```python\nimport hashlib, hmac, time\n\ndef verify_notifynow(raw_body: bytes, headers: dict, secret: str, tolerance_sec: int = 300) -> bool:\n    try:\n        ts = int(headers.get("X-Webhook-Timestamp", ""))\n    except ValueError:\n        return False\n    if abs(time.time() - ts) > tolerance_sec:\n        return False\n    expected = hmac.new(secret.encode(), f"{ts}.".encode() + raw_body, hashlib.sha256).hexdigest()\n    given = [p.strip()[3:] for p in headers.get("X-Webhook-Signature", "").split(",") if p.strip().startswith("v1=")]\n    return any(hmac.compare_digest(g, expected) for g in given)\n```\n\n### PHP\n\n```php\n<?php\nfunction verify_notifynow(string $rawBody, array $headers, string $secret, int $toleranceSec = 300): bool {\n    $ts = $headers[\'X-Webhook-Timestamp\'] ?? \'\';\n    if (!ctype_digit($ts) || abs(time() - (int) $ts) > $toleranceSec) return false;\n    $expected = hash_hmac(\'sha256\', $ts . \'.\' . $rawBody, $secret);\n    foreach (explode(\',\', $headers[\'X-Webhook-Signature\'] ?? \'\') as $part) {\n        $part = trim($part);\n        if (str_starts_with($part, \'v1=\') && hash_equals($expected, substr($part, 3))) return true;\n    }\n    return false;\n}\n// $ok = verify_notifynow(file_get_contents(\'php://input\'), getallheaders(), getenv(\'NOTIFYNOW_WEBHOOK_SECRET\'));\n```\n\n## Retries, disabling and replay\n\n- Failed deliveries are retried after **1 min, 5 min, 30 min, 2 h and 12 h** (6 attempts), always with the same `id`.\n- After **5 events given up in a row**, or **24 hours of failures**, the endpoint is turned off and owners / admins get a notification and an e-mail. Turn it on again after fixing the receiver.\n- The delivery log (30 days) shows each attempt\'s status code, time and the first 1 KB of your answer. **Replay** sends a delivery again now.\n- **Send test event** posts a sample of any event type and shows your answer.\n- Events are not ordered; use `createdAt` and the ids in `data`.\n\n## Personal data\n\nBy default payloads carry ids, statuses, outcomes and amounts only. Turn on **Include personal data** for an endpoint to also get `phone`, `name`, the call `summary` and message `text`.\n\n## Events\n\n| Event                                                                    | When                                                                        |\n| ------------------------------------------------------------------------ | --------------------------------------------------------------------------- |\n| `call.started`                                                           | a call is answered                                                          |\n| `call.completed`                                                         | a call ended (any status) and its cost is settled                           |\n| `call.insights.ready`                                                    | the post-call AI summary / outcome is ready (or skipped)                    |\n| `call.missed`                                                            | an incoming phone call nobody (person or AI) took — your callback list      |\n| `campaign.completed`                                                     | a campaign (or a recurring run) finished                                    |\n| `whatsapp.message.received`                                              | a customer message arrived                                                  |\n| `whatsapp.message.status`                                                | one of your messages was sent / delivered / read / failed                   |\n| `whatsapp.call.started` · `whatsapp.call.ended` · `whatsapp.call.missed` | WhatsApp calls                                                              |\n| `contact.opted_out` · `contact.opted_in`                                 | STOP / START or a do-not-call change                                        |\n| `whatsapp_campaign.completed` · `whatsapp_campaign.paused`               | a WhatsApp bulk campaign finished, or paused (by a person or automatically) |\n\nThe `data` of each event, with samples, is listed in [Event payloads](#event-payloads).\n\n## Event payloads\n\nThe `data` of each event (made-up values). Fields marked personal — `phone`, `name`, `summary`, `text` — are sent only to endpoints with **Include personal data**.\n\n### `call.started`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "externalRef": "loan-1001",\n  "provider": "dryrun",\n  "direction": "outbound",\n  "campaignId": "6720f0a1b2c3d4e5f6a7b8cb",\n  "flowId": "6720f0a1b2c3d4e5f6a7b8cc",\n  "agentId": null,\n  "did": null,\n  "phone": "+919876543210",\n  "name": "Asha Verma"\n}\n```\n\n`direction` is `inbound` for a call the customer made to your number (Phase 20); `did` is then that number (E.164), else `null`.\n\n### `call.completed`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "externalRef": "loan-1001",\n  "provider": "dryrun",\n  "direction": "outbound",\n  "campaignId": "6720f0a1b2c3d4e5f6a7b8cb",\n  "flowId": "6720f0a1b2c3d4e5f6a7b8cc",\n  "agentId": null,\n  "did": null,\n  "status": "completed",\n  "endReason": "hangup_node",\n  "durationSec": 94,\n  "costMicros": 2350000,\n  "disposition": "promise_to_pay",\n  "dispositionSource": "flow",\n  "recording": true,\n  "phone": "+919876543210",\n  "name": "Asha Verma"\n}\n```\n\n### `call.missed`\n\nAn incoming phone call to one of your numbers that nobody took. `reason`: `no_answer` (the team did not pick up), `no_agents` (nobody was free), `after_hours`, `line_busy`, `wallet_low`, `caller_hung_up` (gave up while it rang) or `spam` (too many calls from one number; not on the callback list). `phone` is `null` when the caller hid their number.\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "did": "+911600000001",\n  "numberLabel": "Support line",\n  "reason": "no_answer",\n  "at": "2026-11-06T10:15:00.000Z",\n  "phone": "+919876543210",\n  "name": "Asha Verma"\n}\n```\n\n### `call.insights.ready`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "externalRef": "loan-1001",\n  "status": "done",\n  "sentiment": "positive",\n  "disposition": "promise_to_pay",\n  "keyInfo": {\n    "promiseDate": "2026-11-05",\n    "promiseAmountMicros": 2500000000\n  },\n  "summary": "The customer agreed to pay ₹2,500 on 5 November."\n}\n```\n\n### `campaign.completed`\n\n`line` is `phone` (SIP / test line), `whatsapp` (WhatsApp call campaign) or `voice_api` (recorded voice / IVR).\n\n```json\n{\n  "campaignId": "6720f0a1b2c3d4e5f6a7b8cb",\n  "line": "phone",\n  "parentId": null,\n  "counts": {\n    "contacts": 120,\n    "calls": 168,\n    "answered": 92,\n    "completed": 115,\n    "failed": 5,\n    "skipped": 0,\n    "canceled": 0\n  },\n  "outcomes": {\n    "promise_to_pay": 31,\n    "callback": 12\n  },\n  "costMicros": 412500000,\n  "dryRun": false\n}\n```\n\n### `whatsapp.message.received`\n\n```json\n{\n  "messageId": "6720f0a1b2c3d4e5f6a7b8cd",\n  "conversationId": "6720f0a1b2c3d4e5f6a7b8ce",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "type": "text",\n  "phone": "+919876543210",\n  "name": "Asha Verma",\n  "text": "I paid this morning"\n}\n```\n\n### `whatsapp.message.status`\n\n```json\n{\n  "messageId": "6720f0a1b2c3d4e5f6a7b8cd",\n  "conversationId": "6720f0a1b2c3d4e5f6a7b8ce",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "externalRef": "reminder-77",\n  "status": "delivered",\n  "errorCode": null,\n  "chargeMicros": 115000\n}\n```\n\n### `whatsapp.call.started`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "direction": "inbound",\n  "answeredBy": "6720f0a1b2c3d4e5f6a7b8d0",\n  "phone": "+919876543210"\n}\n```\n\n### `whatsapp.call.ended`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "direction": "inbound",\n  "durationSec": 182,\n  "answeredBy": "6720f0a1b2c3d4e5f6a7b8d0",\n  "phone": "+919876543210"\n}\n```\n\n### `whatsapp.call.missed`\n\n```json\n{\n  "callId": "6720f0a1b2c3d4e5f6a7b8c9",\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "direction": "inbound",\n  "phone": "+919876543210"\n}\n```\n\n### `contact.opted_out`\n\n```json\n{\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "channel": "whatsapp",\n  "source": "stop_keyword",\n  "phone": "+919876543210"\n}\n```\n\n### `contact.opted_in`\n\n```json\n{\n  "contactId": "6720f0a1b2c3d4e5f6a7b8ca",\n  "contactExternalId": "CUST-1001",\n  "channel": "whatsapp",\n  "source": "start_keyword",\n  "phone": "+919876543210"\n}\n```\n\n### `whatsapp_campaign.completed`\n\nA WhatsApp bulk campaign sent to everyone it could. Counters keep moving afterwards (late delivery / read / reply); read them with `GET /whatsapp-campaigns/{id}`.\n\n```json\n{\n  "campaignId": "6720f0a1b2c3d4e5f6a7b8cb",\n  "name": "November EMI reminder",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "status": "completed",\n  "pauseReason": null,\n  "counts": {\n    "recipients": 1250,\n    "sent": 1200,\n    "delivered": 1180,\n    "read": 910,\n    "replied": 64,\n    "failed": 20,\n    "skipped": 30\n  },\n  "chargedMicros": 138000000\n}\n```\n\n### `whatsapp_campaign.paused`\n\nPaused by a person (`pauseReason: user`) or automatically: `wallet_empty`, `template_paused`, `quality_red`, `channel_down`.\n\n```json\n{\n  "campaignId": "6720f0a1b2c3d4e5f6a7b8cb",\n  "name": "November EMI reminder",\n  "channelId": "6720f0a1b2c3d4e5f6a7b8cf",\n  "status": "paused",\n  "pauseReason": "wallet_empty",\n  "counts": {\n    "recipients": 1250,\n    "sent": 640,\n    "delivered": 610,\n    "read": 402,\n    "replied": 21,\n    "failed": 4,\n    "skipped": 30\n  },\n  "chargedMicros": 73600000\n}\n```\n',
  versioning:
    '# Versioning\n\nThe API version is **`2026-10`**; webhook payloads carry it as `apiVersion`.\n\n- **Additive changes ship without a new version:** new routes, new optional fields in requests, new fields in answers and webhook payloads, new webhook event types, new error codes. Write clients that ignore unknown fields and unknown events.\n- **Breaking changes** (removing / renaming a field, changing a type or a status code) come only with a new version. The old version keeps working for **6 months** after the announcement; key owners get an e-mail and the change is listed in the changelog.\n- Status values and enums can gain new members; handle unknown values gracefully.\n',
  troubleshooting:
    "# Troubleshooting\n\n| You see                                | Fix                                                                                       |\n| -------------------------------------- | ----------------------------------------------------------------------------------------- |\n| `401 AUTH_UNAUTHENTICATED`             | Send `X-API-Key`; check the key was not revoked or regenerated.                           |\n| `403` with `details[0].path = \"scope\"` | Edit the key and add that scope.                                                          |\n| `403 API_KEY_IP_DENIED`                | Add your server's public IP to the key's allowlist.                                       |\n| `404` on an id you know                | It belongs to another account or was deleted.                                             |\n| `409 WHATSAPP_WINDOW_CLOSED`           | Send a template, not text.                                                                |\n| `409 TEMPLATE_NOT_APPROVED`            | Wait for WhatsApp's approval or use an approved template.                                 |\n| `409 WHATSAPP_CALL_PERMISSION_MISSING` | Ask the customer for call permission from that number first.                              |\n| `409 CAMPAIGN_NOT_RUNNABLE`            | Read `details`: a flow not published, an agent off, audio deleted, empty audience.        |\n| `422 VALIDATION_FAILED`                | Each `details[]` entry names the field. Unknown fields are refused too.                   |\n| `422 IDEMPOTENCY_KEY_REUSED`           | You reused a key for a different body — use a new key.                                    |\n| `422 WALLET_INSUFFICIENT_BALANCE`      | Add money; paused campaigns with auto-resume continue.                                    |\n| `429 RATE_LIMITED`                     | Wait `Retry-After`; batch your work.                                                      |\n| Webhook signature fails                | Use the raw body bytes, the exact secret, and a clock within 5 minutes.                   |\n| No webhooks arrive                     | Check the endpoint is active (it disables after repeated failures), then **Replay**.      |\n| Calls stay `queued`                    | The account is on the test line, outside the calling window, or at its concurrency limit. |\n\nThe key's request log (Settings → API keys) shows every call it made in the last 7 days. Quote the `requestId` from an error to support.\n",
  changelog:
    '# API changelog\n\n- **2026-11-05:**\n  - **Account resources** (`resources:read`): `GET /resources/flows`, `/agents`, `/whatsapp-numbers`, `/contact-lists`, `/segments`, `/phone-line`, `/ivrs`, `/wallet`.\n  - **WhatsApp bulk campaigns** with API keys (`whatsapp-campaigns:read` / `:write`): create, estimate, start, pause, resume, stop, retry failed, recipients, export, report.\n  - Webhooks: `whatsapp_campaign.completed`, `whatsapp_campaign.paused`; `campaign.completed` carries `line`.\n  - Recorded-voice / IVR campaigns: `POST /campaigns` with `line: "voice_api"`; calls with `provider: voice_api`; error codes `VOICE_API_*`.\n  - Every route documents its scope (`x-scope`), examples and errors; Postman collection at `/api/v1/postman.json`.\n- **2026-11 (Phase 19):** campaign `line` (`phone` / `whatsapp`) with WhatsApp call campaigns (flow or agent, ask permission first); WhatsApp bulk campaigns in the dashboard; WhatsApp numbers paced at 18 / 75 messages per second.\n- **2026-11 (Phase 18):** real phone calls over the SIP line (`mode: live`), caller numbers, answering machine detection (`phoneLine.amd`), new end reasons (`machine`, `rejected_by_customer`).\n- **2026-10 (Phase 15):** the public API opens:\n  - API keys with 13 scopes, an IP allowlist, expiry, per-key limits and a 7-day request log.\n  - Contacts upsert and bulk upsert; WhatsApp template and text sends with message status; `externalRef` on calls and messages; WhatsApp AI calls.\n  - Outbound webhooks with 11 events, HMAC-SHA256 signatures, retries, replay and a test event.\n  - Webhook payloads carry `apiVersion: "2026-10"`.\n',
};
